/**
 * GBU One - local Expo config plugin: Android release signing and 16 KB
 * page sizes.
 *
 * The `android/` folder is generated by `expo prebuild` and is not committed,
 * so the release configuration has to be injected by a plugin that runs on
 * every prebuild.
 *
 * The plugin reads the signing material from the environment (settable in
 * `.env` for a local build, or as secrets in the release pipeline):
 *
 *   GBU_ANDROID_KEYSTORE_PATH     path to the .jks / .keystore file
 *   GBU_ANDROID_KEYSTORE_PASSWORD  keystore password
 *   GBU_ANDROID_KEY_ALIAS          key alias
 *   GBU_ANDROID_KEY_PASSWORD       key password
 *
 * When the values are missing a RELEASE build FAILS CLOSED: there is no
 * fallback to the debug key, because a debug-signed "release" can never be
 * updated on the Play Store and the mistake stays invisible until the
 * upload is rejected. The generated Gradle script throws, and a build that
 * is explicitly marked as a release (`GBU_RELEASE_BUILD=1`) is stopped even
 * earlier - during the prebuild. A DEBUG build still uses the debug key;
 * that is what debug builds are for.
 *
 * EAS managed signing is supported as well: when the owner does not use
 * the GBU_ANDROID_* variables, the standard `MYAPP_UPLOAD_*` variables that
 * EAS injects are used instead. Both are resolved at BUILD time, so a
 * credential never has to be written into the repository.
 *
 * The plugin also pins the NDK to r27 and enables the CMake flexible page
 * sizes, so the native libraries this project compiles itself are 16 KB
 * aligned for Android 15+. The prebuilt React Native 0.76 binaries still are
 * not - see docs/OPEN_QUESTIONS.md #13.
 */
const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('@expo/config-plugins');

/** The four variables a release build needs. */
const SIGNING_VARIABLES = [
  'GBU_ANDROID_KEYSTORE_PATH',
  'GBU_ANDROID_KEYSTORE_PASSWORD',
  'GBU_ANDROID_KEY_ALIAS',
  'GBU_ANDROID_KEY_PASSWORD',
];

const SIGNING_BLOCK = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        release {
            // The owner keystore. It may come from gradle.properties (the
            // local build writes the values there) or from the environment
            // (EAS managed signing injects MYAPP_UPLOAD_*).
            storeFile file(project.findProperty('GBU_KEYSTORE_FILE') ?: System.getenv('GBU_ANDROID_KEYSTORE_PATH') ?: System.getenv('MYAPP_UPLOAD_STORE_FILE') ?: 'MISSING_GBU_KEYSTORE')
            storePassword project.findProperty('GBU_KEYSTORE_PASSWORD') ?: System.getenv('GBU_ANDROID_KEYSTORE_PASSWORD') ?: System.getenv('MYAPP_UPLOAD_STORE_PASSWORD') ?: ''
            keyAlias project.findProperty('GBU_KEY_ALIAS') ?: System.getenv('GBU_ANDROID_KEY_ALIAS') ?: System.getenv('MYAPP_UPLOAD_KEY_ALIAS') ?: ''
            keyPassword project.findProperty('GBU_KEY_PASSWORD') ?: System.getenv('GBU_ANDROID_KEY_PASSWORD') ?: System.getenv('MYAPP_UPLOAD_KEY_PASSWORD') ?: ''
        }
    }
`;

const RELEASE_BLOCK = `        release {
            // FAIL CLOSED. A release build must be signed with the owner
            // keystore. There is deliberately NO fallback to the debug key:
            // a debug-signed "release" can never be updated on the Play
            // Store, and the mistake stays invisible until the upload is
            // rejected. Stop the build instead.
            def storeFilePath = project.findProperty('GBU_KEYSTORE_FILE') ?: System.getenv('GBU_ANDROID_KEYSTORE_PATH') ?: System.getenv('MYAPP_UPLOAD_STORE_FILE')
            def requestedTasks = gradle.startParameter.taskNames.collect { it.toLowerCase() }
            def releaseRequested = requestedTasks.any { t -> t.contains('release') || t == 'build' || t == 'assemble' || t == 'bundle' }
            if (storeFilePath && file(storeFilePath).exists()) {
                signingConfig signingConfigs.release
            } else if (releaseRequested) {
                throw new GradleException("REFUSING TO BUILD: a release build must be signed with the owner keystore. Set GBU_ANDROID_KEYSTORE_PATH, GBU_ANDROID_KEYSTORE_PASSWORD, GBU_ANDROID_KEY_ALIAS and GBU_ANDROID_KEY_PASSWORD (see docs/RELEASE.md), or use EAS managed signing.")
            }
            shrinkResources (findProperty('android.enableShrinkResourcesInReleaseBuilds')?.toBoolean() ?: false)
            minifyEnabled enableProguardInReleaseBuilds
            proguardFiles getDefaultProguardFile("proguard-android.txt"), "proguard-rules.pro"
            crunchPngs (findProperty('android.enablePngCrunchInReleaseBuilds')?.toBoolean() ?: true)
        }
`;

/**
 * Android 15+ runs apps whose native libraries are not built for 16 KB
 * pages in a compatibility mode, and Google Play requires 16 KB support for
 * new uploads. NDK r27 links with a 16 KB max page size and
 * ANDROID_SUPPORT_FLEXIBLE_PAGE_SIZES lets the CMake-built modules
 * (reanimated, worklets, expo-modules-core, ...) use it too.
 */
const NDK_VERSION = '27.1.12297006';
const PAGE_SIZE_CMAKE_ARGS = `            externalNativeBuild {
                cmake {
                    arguments '-DANDROID_SUPPORT_FLEXIBLE_PAGE_SIZES=ON'
                }
            }
`;

/** Replaces the generated signingConfigs / release buildType blocks. */
function patchBuildGradle(source) {
  let output = source;

  // signingConfigs: keep the generated debug block, add a release block.
  const signingConfigsRe = /signingConfigs\s*\{[\s\S]*?\n    \}\n/;
  if (signingConfigsRe.test(output)) {
    output = output.replace(signingConfigsRe, `${SIGNING_BLOCK}\n`);
  }

  // release buildType: use the owner keystore when it is available.
  const releaseRe =
    /release\s*\{\n\s*\/\/ Caution![^\n]*\n\s*\/\/ see[^\n]*\n\s*signingConfig signingConfigs\.debug\n[\s\S]*?\n        \}\n/;
  if (releaseRe.test(output)) {
    output = output.replace(releaseRe, RELEASE_BLOCK);
  }

  // defaultConfig: build the native modules for 16 KB pages.
  if (!output.includes('ANDROID_SUPPORT_FLEXIBLE_PAGE_SIZES')) {
    const defaultConfigRe = /(\n    defaultConfig \{\n)/;
    if (defaultConfigRe.test(output)) {
      output = output.replace(defaultConfigRe, `$1${PAGE_SIZE_CMAKE_ARGS}`);
    }
  }

  // A standalone debug build must carry its own JS bundle, otherwise it
  // only runs with a Metro dev server attached. This is what the on-device
  // QA build relies on.
  if (!/debuggableVariants\s*=\s*\[\]/.test(output)) {
    const variantsRe = /(\n[ \t]*\/\* Variants \*\/[^\n]*\n)/;
    if (variantsRe.test(output)) {
      output = output.replace(
        variantsRe,
        `$1    // Ensure standalone debug builds also embed the JS bundle and assets\n    debuggableVariants = []\n`,
      );
    }
  }

  return output;
}

/** Bumps the NDK to r27 so the linker emits 16 KB aligned objects. */
function patchRootBuildGradle(source) {
  return source.replace(
    /ndkVersion\s*=\s*"[\d.]+"/,
    `ndkVersion = "${NDK_VERSION}"`,
  );
}

/**
 * Escapes a value for a Java .properties file.
 * A Windows path such as `C:\keys\release.jks` contains a colon, which the
 * properties format would otherwise read as a key/value separator.
 */
function escapePropertyValue(value) {
  return String(value).replace(/\\/g, '\\\\').replace(/:/g, '\\:');
}

/** The signing values Gradle needs, or an empty list when none are set. */
function signingProperties() {
  const lines = [];
  if (process.env.GBU_ANDROID_KEYSTORE_PATH) {
    lines.push(`GBU_KEYSTORE_FILE=${escapePropertyValue(process.env.GBU_ANDROID_KEYSTORE_PATH)}`);
  }
  if (process.env.GBU_ANDROID_KEYSTORE_PASSWORD) {
    lines.push(`GBU_KEYSTORE_PASSWORD=${escapePropertyValue(process.env.GBU_ANDROID_KEYSTORE_PASSWORD)}`);
  }
  if (process.env.GBU_ANDROID_KEY_ALIAS) {
    lines.push(`GBU_KEY_ALIAS=${escapePropertyValue(process.env.GBU_ANDROID_KEY_ALIAS)}`);
  }
  if (process.env.GBU_ANDROID_KEY_PASSWORD) {
    lines.push(`GBU_KEY_PASSWORD=${escapePropertyValue(process.env.GBU_ANDROID_KEY_PASSWORD)}`);
  }
  return lines;
}

/**
 * Stops a build that is explicitly marked as a RELEASE build when the
 * owner keystore is not available.
 *
 * `tools/build_android_apk.py --release` sets GBU_RELEASE_BUILD=1 for the
 * prebuild, so the build stops in seconds with a readable message instead
 * of failing ten minutes later inside Gradle. A build that is not marked
 * as a release (a debug build, a plain `expo prebuild`) is never stopped
 * here - the Gradle script applies the same rule to the release variant.
 */
function assertReleaseSigningAvailable() {
  const flag = String(process.env.GBU_RELEASE_BUILD || '').toLowerCase();
  if (!['1', 'true', 'yes'].includes(flag)) return;

  const missing = SIGNING_VARIABLES.filter((name) => !process.env[name]);
  if (missing.length > 0) {
    throw new Error(
      `REFUSING TO BUILD: a release build needs ${missing.join(', ')}. ` +
        'The release build is signed with the owner keystore - there is no ' +
        'debug-key fallback (see docs/RELEASE.md).',
    );
  }

  const keystore = process.env.GBU_ANDROID_KEYSTORE_PATH;
  if (!fs.existsSync(keystore)) {
    throw new Error(
      `REFUSING TO BUILD: the keystore ${keystore} does not exist. ` +
        'Check GBU_ANDROID_KEYSTORE_PATH (see docs/RELEASE.md).',
    );
  }
}

/**
 * Patches android/app/build.gradle and android/gradle.properties.
 * A dangerous mod is used on purpose: it runs after prebuild has written the
 * native files, which is the only point where the generated Gradle script
 * exists in its final shape.
 */
function withAndroidSigningFiles(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const androidRoot = cfg.modRequest.platformProjectRoot;

      // 0. A release build without the owner keystore stops HERE.
      assertReleaseSigningAvailable();

      // 1. gradle.properties: hand the signing values to Gradle.
      const propertiesFile = path.join(androidRoot, 'gradle.properties');
      if (fs.existsSync(propertiesFile)) {
        const current = fs.readFileSync(propertiesFile, 'utf8');
        const filtered = current
          .split('\n')
          .filter((line) => !/^GBU_KEY/.test(line))
          .join('\n');
        const lines = signingProperties();
        fs.writeFileSync(
          propertiesFile,
          lines.length > 0 ? `${filtered}\n${lines.join('\n')}\n` : `${filtered}\n`,
          'utf8',
        );
      }

      // 2. app/build.gradle: add the release signing config and the
      //    16 KB page-size flags.
      const buildGradleFile = path.join(androidRoot, 'app', 'build.gradle');
      if (fs.existsSync(buildGradleFile)) {
        const current = fs.readFileSync(buildGradleFile, 'utf8');
        fs.writeFileSync(buildGradleFile, patchBuildGradle(current), 'utf8');
      }

      // 3. build.gradle (project root): NDK r27 links 16 KB aligned objects.
      const rootBuildGradleFile = path.join(androidRoot, 'build.gradle');
      if (fs.existsSync(rootBuildGradleFile)) {
        const current = fs.readFileSync(rootBuildGradleFile, 'utf8');
        fs.writeFileSync(rootBuildGradleFile, patchRootBuildGradle(current), 'utf8');
      }

      // 4. local.properties: `expo prebuild --clean` removes it, and the
      //    Android build then cannot find the SDK. Restore it from ANDROID_HOME
      //    so a clean prebuild still builds.
      const localPropertiesFile = path.join(androidRoot, 'local.properties');
      if (!fs.existsSync(localPropertiesFile)) {
        const sdkRoot =
          process.env.ANDROID_HOME ||
          process.env.ANDROID_SDK_ROOT ||
          (process.env.LOCALAPPDATA
            ? path.join(process.env.LOCALAPPDATA, 'Android', 'Sdk')
            : '');
        if (sdkRoot && fs.existsSync(sdkRoot)) {
          // Forward slashes: the properties format treats a backslash as an
          // escape character.
          const sdkDir = sdkRoot.replace(/\\/g, '/');
          fs.writeFileSync(localPropertiesFile, `sdk.dir=${sdkDir}\n`, 'utf8');
        }
      }

      // 5. MainActivity.kt: unlock 120Hz high refresh rate and hardware acceleration
      const mainActivityPath = path.join(
        androidRoot,
        'app',
        'src',
        'main',
        'java',
        'in',
        'gbu',
        'one',
        'MainActivity.kt',
      );
      if (fs.existsSync(mainActivityPath)) {
        let code = fs.readFileSync(mainActivityPath, 'utf8');
        if (!code.includes('enableHighRefreshRate')) {
          const target = 'super.onCreate(null)';
          const replacement = `super.onCreate(null)\n    enableHighRefreshRate()\n  }\n\n  override fun onWindowFocusChanged(hasFocus: Boolean) {\n    super.onWindowFocusChanged(hasFocus)\n    if (hasFocus) {\n      enableHighRefreshRate()\n    }\n  }\n\n  private fun enableHighRefreshRate() {\n    try {\n      window.setFlags(\n        android.view.WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED,\n        android.view.WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED\n      )\n      if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.R) {\n        val currentDisplay = display\n        val modes = currentDisplay?.supportedModes\n        val highestMode = modes?.maxByOrNull { it.refreshRate }\n        if (highestMode != null && highestMode.refreshRate > 60f) {\n          window.attributes.preferredDisplayModeId = highestMode.modeId\n        }\n        window.attributes.preferredRefreshRate = 120f\n      } else if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.M) {\n        @Suppress("DEPRECATION")\n        val wm = getSystemService(android.content.Context.WINDOW_SERVICE) as? android.view.WindowManager\n        @Suppress("DEPRECATION")\n        val display = wm?.defaultDisplay\n        @Suppress("DEPRECATION")\n        val modes = display?.supportedModes\n        val highestMode = modes?.maxByOrNull { it.refreshRate }\n        if (highestMode != null && highestMode.refreshRate > 60f) {\n          val params = window.attributes\n          params.preferredDisplayModeId = highestMode.modeId\n          window.attributes = params\n        }\n      }\n    } catch (_: Exception) {}\n  `;
          code = code.replace(target, replacement);
          fs.writeFileSync(mainActivityPath, code, 'utf8');
        }
      }

      // 6. AndroidManifest.xml: ensure hardwareAccelerated and largeHeap
      const manifestPath = path.join(androidRoot, 'app', 'src', 'main', 'AndroidManifest.xml');
      if (fs.existsSync(manifestPath)) {
        let manifest = fs.readFileSync(manifestPath, 'utf8');
        if (!manifest.includes('android:largeHeap="true"')) {
          manifest = manifest.replace(
            '<application ',
            '<application android:hardwareAccelerated="true" android:largeHeap="true" ',
          );
          manifest = manifest.replace(
            '<activity ',
            '<activity android:hardwareAccelerated="true" ',
          );
          fs.writeFileSync(manifestPath, manifest, 'utf8');
        }
      }

      return cfg;
    },
  ]);
}

/** @type {import('@expo/config-plugins').ConfigPlugin} */
const withReleaseSigning = (config) => withAndroidSigningFiles(config);

module.exports = withReleaseSigning;
